  const prereqBlock='<div id="plan-prereqs">'+(p.prerequisites.length?p.prerequisites.map((a,i)=>prereqCard(s,a,i)).join(''):'<p class="calc-empty">Nenhuma compra antes do seu objetivo. Adicione o que você precisa comprar primeiro (equipamento, veículo, imóvel…), se houver.</p>')+'</div>'+combobox('plan-prereq-search','Adicionar uma compra prévia (busque no site)','plan-prereq')+btn('Adicionar uma compra livre','data-b-plan-p-add="1"')+'<div class="calc-fields">'+select('plan.strategy','Em que ordem comprar?',Object.entries(STRATEGY_LABEL),p.strategy)+field('plan.situation.upkeepPerSession','Gasto por sessão ($): consumíveis, munição…',si.upkeepPerSession,{id:'plan-upkeep',hint:'Descontado do que você ganha. Coloque 0 se não souber.'})+'</div>';
  const form='<div class="b-plan-import"><p class="calc-note">O plano de negócios tem seus próprios campos: nada é puxado automaticamente dos oito cálculos. Se você quiser partir dos seus números de Meus cálculos, clique aqui e depois mude o que quiser.</p>'+btn('Usar meus números de Meus cálculos','data-b-plan-import-calcs="1"')+'</div><div class="calc-fields calc-steps">'
   +step(1,'Qual é o seu objetivo?',select('plan.goal.kind','Meu objetivo',Object.entries(KIND_LABEL),g.kind)+goalBlock,'O objetivo decide todo o resto: uma compra tem um preço, uma quantia se ganha aos poucos, um desbloqueio se ganha com pontos.')
   +step(2,'Em que ponto você está?','<div class="calc-fields">'+field('plan.situation.capital','Já tenho ($)',si.capital,{id:'plan-capital'})+field('plan.situation.reserve','Dinheiro que deixo guardado ($)',si.reserve,{id:'plan-reserve'})+field('plan.situation.dailyMinutes','Uma sessão dura (minutos)',si.dailyMinutes,{id:'plan-daily',min:1,max:1440,hint:'O programa é feito sessão por sessão. Deixe vazio se você não conta em sessões: você terá um percurso em tempo de jogo, sem calendário.'})+field('plan.situation.daysPerWeek','Quantos dias por semana eu jogo?',si.daysPerWeek,{id:'plan-days',min:1,max:7,integer:true})+field('plan.situation.players','Quantos de nós jogamos (jogadores)',si.players??1,{id:'plan-players',min:1,max:100,integer:true,hint:'Uma missão que exige mais jogadores do que o seu grupo fica fora do plano, e isso é avisado.'})+'</div>','Com o que você tem e a duração das suas sessões, o plano conta em sessões e depois em dias.')
   +step(3,'Como você ganha seu dinheiro?',select('plan.source','Ganho meu dinheiro',[['missions','Com minhas missões: o plano me diz quais fazer e em que ordem'],['hourly','Aos poucos: ganho um valor mais ou menos fixo por hora']],p.source)+missionsBlock,'Com as suas missões, o plano escolhe a cada sessão as que mais rendem no tempo que você tem. É o caminho mais rápido que ele encontra.')
