  const sessCash=(()=>{if(!before.valid||before.continuous||S0===null||!Array.isArray(before.sessions))return null;const ss=before.sessions,q=Math.floor(played/S0+1e-9),f=played/S0-q;if(q>ss.length||(q===ss.length&&f>1e-9))return null;const cash=f>1e-9?ss[q].cashBefore+ss[q].gain*f:q>=1?ss[q-1].cashAfter:before.startCash;return Number.isFinite(cash)?cash:null;})();
