 function shortSummary(s){const r=B.evaluate('plan',s);const name=goalName(s);if(!r.valid)return 'Meta: '+name+' · plano a completar ('+r.reason+')';return 'Meta: '+name+' · '+(r.totalSessions===0||(r.continuous&&r.totalMinutes===0)?'já é possível':r.continuous?timeText(r):plural(r.totalSessions,' sessão',' sessões')+' de '+sessionLabel(s)+' · '+plural(r.days,' dia',' dias'))+' · '+(s.plan.source==='missions'?plural(s.plan.missions.length,' missão',' missões'):money(s.plan.situation.hourly)+'/h')+(r.purchases.some(x=>x.atSession)?' · '+plural(r.purchases.filter(x=>x.atSession).length,' compra',' compras')+' antes do objetivo':'');}
